using System.ComponentModel.DataAnnotations;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Settings;[Authorize]public sealed class IndexModel(MediStockDbContext db,AuthService auth):PageModel{[BindProperty]public SettingsInput Input{get;set;}=new();[TempData]public string?StatusMessage{get;set;}
public async Task OnGetAsync(){var values=(await db.AppSettings.AsNoTracking().ToListAsync()).ToDictionary(x=>x.Key,x=>x.Value);Input=new SettingsInput{PharmacyName=Get(values,"PharmacyName","MediStock Pharmacy"),PharmacyAddress=Get(values,"PharmacyAddress",""),ContactNumber=Get(values,"PharmacyContact",""),Currency=Get(values,"Currency","LKR"),LowStockQuantity=int.TryParse(Get(values,"LowStockQuantity","10"),out var l)?l:10,ExpiryWarningDays=int.TryParse(Get(values,"ExpiryWarningDays","30"),out var e)?e:30,Theme=Get(values,"Theme","Light")};}
public async Task<IActionResult>OnPostSaveAsync(){await Save("PharmacyName",Input.PharmacyName);await Save("PharmacyAddress",Input.PharmacyAddress);await Save("PharmacyContact",Input.ContactNumber);await Save("Currency",Input.Currency);await Save("LowStockQuantity",Input.LowStockQuantity.ToString());await Save("ExpiryWarningDays",Input.ExpiryWarningDays.ToString());await Save("Theme",Input.Theme);await db.SaveChangesAsync();StatusMessage="Settings saved.";return RedirectToPage();}
public IActionResult OnPostBackup(){var path=Path.Combine(Path.GetTempPath(),$"MediStock-backup-{DateTime.UtcNow:yyyyMMdd-HHmmss}.db");var backup=auth.BackupDatabase(path);var bytes=System.IO.File.ReadAllBytes(backup);return File(bytes,"application/vnd.sqlite3",$"MediStock-backup-{DateTime.UtcNow:yyyyMMdd}.db");}
public async Task<IActionResult>OnPostRestoreAsync(IFormFile? BackupFile){if(BackupFile is null||BackupFile.Length==0){StatusMessage="Select a valid backup file.";return RedirectToPage();}var temp=Path.Combine(Path.GetTempPath(),$"medistock-restore-{Guid.NewGuid():N}.db");await using(var stream=System.IO.File.Create(temp)){await BackupFile.CopyToAsync(stream);}auth.RestoreDatabase(temp);System.IO.File.Delete(temp);StatusMessage="Database restored.";return RedirectToPage();}
private async Task Save(string key,string value){var x=await db.AppSettings.FindAsync(key);if(x is null)db.AppSettings.Add(new AppSetting{Key=key,Value=value});else x.Value=value;}private static string Get(Dictionary<string,string>v,string key,string fallback)=>v.TryGetValue(key,out var value)?value:fallback;}
public sealed class SettingsInput{[Required,StringLength(120)]public string PharmacyName{get;set;}="MediStock Pharmacy";[StringLength(500)]public string PharmacyAddress{get;set;}="";[Phone,StringLength(30)]public string ContactNumber{get;set;}="";[Required]public string Currency{get;set;}="LKR";[Range(0,100000)]public int LowStockQuantity{get;set;}=10;[Range(1,365)]public int ExpiryWarningDays{get;set;}=30;public string Theme{get;set;}="Light";}
